import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Kernel (@deepseek-ai/dsh) management","description":"","frontmatter":{},"headers":[],"relativePath":"en/kernel.md","filePath":"en/kernel.md","lastUpdated":null}'),s={name:"en/kernel.md"};function i(o,e,l,d,p,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="kernel-deepseek-ai-dsh-management" tabindex="-1">Kernel (@deepseek-ai/dsh) management <a class="header-anchor" href="#kernel-deepseek-ai-dsh-management" aria-label="Permalink to &quot;Kernel (@deepseek-ai/dsh) management&quot;">​</a></h1><p>The app manages the kernel <code>@deepseek-ai/dsh</code>, which powers the DeepSeek Harness Web UI.</p><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to &quot;Common operations&quot;">​</a></h2><h3 id="first-install" tabindex="-1">First install <a class="header-anchor" href="#first-install" aria-label="Permalink to &quot;First install&quot;">​</a></h3><p>When no kernel is detected, an install wizard appears. You can choose the registry, whether to include pre-releases, and a specific version, then install in one click.</p><h3 id="upgrade-switch-version" tabindex="-1">Upgrade / switch version <a class="header-anchor" href="#upgrade-switch-version" aria-label="Permalink to &quot;Upgrade / switch version&quot;">​</a></h3><p>In <strong>Settings → Kernel</strong>:</p><ul><li><strong>Check / update kernel</strong>: compare with the latest and click “Update kernel” to upgrade.</li><li><strong>Version management</strong>: refresh the version list (filtered by “include pre-releases” and the registry), pick a historical version to install / switch (upgrade or downgrade).</li></ul><p>Upgrades and switches <strong>safely stop dsh first</strong> (asking if one is running), then restart automatically on success to run the target version; on failure the app tries to restore the previous running state and reports the reason.</p><h3 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h3><p>Click “Uninstall kernel” to stop dsh and remove it, then the install wizard reappears. If the uninstall fails, the app detects why the directory is occupied (still referenced by a process, read-only, or blocked by security software) and informs you.</p><h2 id="network-registry" tabindex="-1">Network &amp; registry <a class="header-anchor" href="#network-registry" aria-label="Permalink to &quot;Network &amp; registry&quot;">​</a></h2><p>Kernel version listing, update checks and install / uninstall all use npm. The default is the official <code>registry.npmjs.org</code>; in some regions you can switch to the <code>npmmirror</code> mirror.</p><h2 id="difference-from-app-self-update" tabindex="-1">Difference from app self-update <a class="header-anchor" href="#difference-from-app-self-update" aria-label="Permalink to &quot;Difference from app self-update&quot;">​</a></h2><ul><li><strong>Kernel update</strong>: updates <code>@deepseek-ai/dsh</code> (npm), managed on the Kernel page.</li><li><strong>App self-update</strong>: updates the shell app itself (GitHub releases), managed on the About page.</li></ul>',15)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
